import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"State of the Cephalopod - India 2026","description":"","frontmatter":{"title":"State of the Cephalopod - India 2026","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph","distributed storage","开源社区","存储技术","Ceph Days India"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/State_of_the_Cephalopod_-_India_2026.md","filePath":"posts/2026/State_of_the_Cephalopod_-_India_2026.md","lastUpdated":1780459816000}'),i={name:"posts/2026/State_of_the_Cephalopod_-_India_2026.md"};function l(h,a,n,s,p,d){return o(),t("div",null,[...a[0]||(a[0]=[r('<h2 id="活动背景与欢迎致辞" tabindex="-1">活动背景与欢迎致辞 <a class="header-anchor" href="#活动背景与欢迎致辞" aria-label="Permalink to &quot;活动背景与欢迎致辞&quot;">​</a></h2><p>本次活动为 Ceph Days2026 India 章节，在印度班加罗尔举办，是该地点举办的第四届 Ceph Day，也是迄今为止参与人数最多的一届。活动由 IBM 主办，主持人 Vinayak（IBM QA 测试开发工程师）和 Shukha（IBM 软件包开发工程师）共同主持。IBM 项目总监 Viri 和 SA 管理项目总监 Sina 代表 IBM 发表欢迎致辞，对社区成员克服班加罗尔交通不便前来参会表示感谢。</p><h2 id="主题演讲-ceph-项目现状-state-of-the-cephalopod" tabindex="-1">主题演讲：Ceph 项目现状（State of the Cephalopod） <a class="header-anchor" href="#主题演讲-ceph-项目现状-state-of-the-cephalopod" aria-label="Permalink to &quot;主题演讲：Ceph 项目现状（State of the Cephalopod）&quot;">​</a></h2><p>主讲人为 IBM 产品项目总监、Ceph 核心开发团队负责人，同时也是 Ceph 执行委员会成员及 Ceph 基金会治理委员会成员，曾长期担任 RADOS 组件技术负责人。</p><h3 id="项目规模与贡献数据" tabindex="-1">项目规模与贡献数据 <a class="header-anchor" href="#项目规模与贡献数据" aria-label="Permalink to &quot;项目规模与贡献数据&quot;">​</a></h3><p>Ceph 从一个博士研究项目发展为企业级存储软件，拥有近 20 年的存储革新历史。当前项目主要指标如下：</p><ul><li>贡献者数量：约 1,500 人</li><li>源代码行数：超过 700,000 行（不含文档和 QA 相关代码）</li><li>总提交次数：超过 160,000 次，且仍在持续增长</li></ul><p>通过 Linux Foundation Insights（LFX）平台对接 GitHub仓库，可以观察到过去五年项目 Star 数量和提交活跃度的持续增长趋势，充分体现了 Ceph 在开发者社区和用户社区中的广泛影响力。</p><h3 id="用户社区增长" tabindex="-1">用户社区增长 <a class="header-anchor" href="#用户社区增长" aria-label="Permalink to &quot;用户社区增长&quot;">​</a></h3><p>Ceph 上游 telemetry 框架数据显示，过去五年中集群总存储容量和已用容量均呈现显著增长态势，截至 2025 年底数据尤为亮眼，印证了 Ceph 用户社区的持续壮大。</p><h3 id="版本发布情况" tabindex="-1">版本发布情况 <a class="header-anchor" href="#版本发布情况" aria-label="Permalink to &quot;版本发布情况&quot;">​</a></h3><p>Ceph 项目保持每年发布一个主要版本的节奏，同时维护两个 backport 版本以支持旧版本用户：</p><ul><li><strong>Tentacle</strong>：2025 年 11 月正式 GA 发布，为当前最新稳定版本</li><li><strong>Umbrella</strong>：正在开发中，将是第 21 个 Ceph 上游版本</li><li><strong>Reef（18.x）</strong>：即将 EOL（End of Life），18.28 版本正在发布中</li><li><strong>Squid</strong>：自 2024 年起持续维护中</li></ul><h3 id="重要里程碑公告" tabindex="-1">重要里程碑公告 <a class="header-anchor" href="#重要里程碑公告" aria-label="Permalink to &quot;重要里程碑公告&quot;">​</a></h3><p>演讲者在本次活动上首次正式宣布：<strong>V 版本已被命名为 Vampire</strong>。Vampire Squid（吸血鬼乌贼）是真实存在的头足类动物，与 Ceph 的命名传统完全吻合。</p><h2 id="社区建设与新举措" tabindex="-1">社区建设与新举措 <a class="header-anchor" href="#社区建设与新举措" aria-label="Permalink to &quot;社区建设与新举措&quot;">​</a></h2><h3 id="ceph-用户委员会-ceph-user-council" tabindex="-1">Ceph 用户委员会（Ceph User Council） <a class="header-anchor" href="#ceph-用户委员会-ceph-user-council" aria-label="Permalink to &quot;Ceph 用户委员会（Ceph User Council）&quot;">​</a></h3><p>该委员会于 2025 年启动，持续成长和成熟。主要工作方式是向生产环境中使用 Ceph 的用户社区发送调查问卷，重点关注 performance、orchestration、usability 等日常运维关切，并将反馈转化为可落地的改进项，包括软件优化、文档改进和 bug 修复等。相关讨论在每月一次的 Ceph UserDev 会议中进行，欢迎社区成员参与。</p><h3 id="社区互动渠道" tabindex="-1">社区互动渠道 <a class="header-anchor" href="#社区互动渠道" aria-label="Permalink to &quot;社区互动渠道&quot;">​</a></h3><ul><li><strong>Slack</strong>：最主流的社区互动平台，设有用户频道、开发者频道和版本讨论频道</li><li><strong>Meetup 群组</strong>：用于发布 UserDev 会议、Ceph Developer Summit 等活动通知</li></ul><h3 id="_2026-年新举措" tabindex="-1">2026 年新举措 <a class="header-anchor" href="#_2026-年新举措" aria-label="Permalink to &quot;2026 年新举措&quot;">​</a></h3><ol><li><strong>Ceph Tech Talks 重启</strong>：2026 年 1 月由 Deepshika Singh 主讲首期，内容为如何在 Sepia Lab 外部环境运行 Teuthology（Ceph 自动化测试框架），所有录像均上传至 YouTube</li><li><strong>Ceph Release Engineering 社区会议</strong>：由 Patrick Donnelly 主导，旨在通过引入更严格的流程来规范版本发布节奏</li><li><strong>Ceph Subreddit 恢复</strong>：此前因故暂停，现已重新开放</li><li><strong>Google Summer of Code（GSoC）</strong>：Ceph 再次入选 GSoC，多个项目和导师参与其中</li></ol><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><h3 id="基础设施迁移" tabindex="-1">基础设施迁移 <a class="header-anchor" href="#基础设施迁移" aria-label="Permalink to &quot;基础设施迁移&quot;">​</a></h3><p>Ceph 上游 Sepia Lab 的所有服务（包括开发、testing、performance 和 release 基础设施）已从 Red Hat 基础设施完成迁移至 IBM 基础设施。此次迁移历时数年，于 2025 年底启动，目前日常运营已全面恢复正常。</p><h3 id="rados-层新特性" tabindex="-1">RADOS 层新特性 <a class="header-anchor" href="#rados-层新特性" aria-label="Permalink to &quot;RADOS 层新特性&quot;">​</a></h3><p><strong>Fast EC（快速 Erasure Coding）</strong> 是本次最受期待的重磅特性，为各类工作负载带来显著的 performance 和容量提升：</p><ul><li>传统上 object storage 配合 erasure coding 已广受欢迎</li><li>Fast EC 现在使 block storage 和 file system storage 工作负载也能使用 erasure coded pools</li><li>鼓励用户积极测试并反馈结果</li></ul><h3 id="rgw-rados-gateway-新特性" tabindex="-1">RGW（RADOS Gateway）新特性 <a class="header-anchor" href="#rgw-rados-gateway-新特性" aria-label="Permalink to &quot;RGW（RADOS Gateway）新特性&quot;">​</a></h3><p>引入 <strong>AWS IAM Accounts</strong> 支持，通过与 AWS 兼容的自助服务 API，为客户和租户提供对角色、身份和权限的细粒度控制。详细信息可参阅 ceph.io 上的专题博客。</p><h3 id="cephfs-新特性" tabindex="-1">CephFS 新特性 <a class="header-anchor" href="#cephfs-新特性" aria-label="Permalink to &quot;CephFS 新特性&quot;">​</a></h3><p>新增 <strong>大小写不敏感目录（Case-Insensitive Directories）</strong> 支持，提升与 kernel cephfs、NFS 和 Samba 的互操作性。</p><h3 id="dashboard-与管理界面" tabindex="-1">Dashboard 与管理界面 <a class="header-anchor" href="#dashboard-与管理界面" aria-label="Permalink to &quot;Dashboard 与管理界面&quot;">​</a></h3><ul><li>IAM Account 管理和多项 RGW 功能已集成至 UI</li><li>新增 SMB、NVMe 相关工作流的 Day 1/Day 2 操作支持</li></ul><h3 id="cephadm-改进" tabindex="-1">cephadm 改进 <a class="header-anchor" href="#cephadm-改进" aria-label="Permalink to &quot;cephadm 改进&quot;">​</a></h3><ul><li>新增 <strong>证书管理（Certificate Management）</strong> 功能</li><li>持续投入 scalability 改进，提升 Ceph Manager 处理大规模 OSD 集群的能力</li></ul><h3 id="crimson-项目进展" tabindex="-1">Crimson 项目进展 <a class="header-anchor" href="#crimson-项目进展" aria-label="Permalink to &quot;Crimson 项目进展&quot;">​</a></h3><p>Crimson 项目配套的新一代 object store <strong>Seastore</strong> 已在 Tentacle 版本中进入 <strong>Tech Preview</strong> 阶段，这是团队的重大里程碑。目前仍在持续优化 performance，欢迎对 performance 感兴趣的用户测试并通过专属 Slack 频道反馈结果。</p><h2 id="近期与未来活动" tabindex="-1">近期与未来活动 <a class="header-anchor" href="#近期与未来活动" aria-label="Permalink to &quot;近期与未来活动&quot;">​</a></h2><ul><li><strong>Cephalocon 2025</strong>：已成功举办</li><li><strong>Ceph Day India 2026</strong>（本次活动）：班加罗尔，2026 年开年首场</li><li><strong>Frankfurt Meetup</strong>：与本次活动同日举行</li><li><strong>Ceph Day Raleigh</strong>：由 IBM赞助，在 IBM Raleigh 办公室举办，即将于下周举行</li><li><strong>Ceph Day London</strong>：计划于 2026 年 6 月举办，将是连续第三届伦敦 Ceph Day</li></ul><p>更多活动信息请关注 Ceph 邮件列表和 Slack 频道。</p><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><p>本次活动由赞助商 <strong>Clyso</strong> 和 <strong>IBM</strong> 提供支持，同时向幕后付出大量心血的组织委员会、评审委员会及全体工作人员致以诚挚感谢。</p>',43)])])}const g=e(i,[["render",l]]);export{u as __pageData,g as default};
